        return ForgeMod.EMPTY_TYPE.get();
    if (fluid == Fluids.WATER || fluid == Fluids.FLOWING_WATER)
        return ForgeMod.WATER_TYPE.get();
    if (fluid == Fluids.LAVA || fluid == Fluids.FLOWING_LAVA)
